import fs from 'node:fs/promises';
import path from 'node:path';
import {Workbook, SpreadsheetFile} from '@oai/artifact-tool';
const dir=path.resolve('scripts/data/count-difference-20261019');
const d=JSON.parse(await fs.readFile(path.join(dir,'initial-audit.json'),'utf8'));
const headers=new Map(d.uncovered_period.map(x=>[x.key.join('/'),x]));
const list=[...d.outside_scope_adjustments].sort((a,b)=>a.invoice.join('/').localeCompare(b.invoice.join('/')));
if(list.length!==287 || new Set(list.map(x=>x.invoice.join('/'))).size!==287) throw Error('Danh sách thiếu hoặc trùng');
const w=Workbook.create();
const s=w.worksheets.add('287 HD ngoai pham vi');
s.getRange('A1:M292').format={font:{name:'Arial',size:10},verticalAlignment:'center',rowHeight:34};
s.getRange('A1:M1').merge();s.getRange('A1').values=[['287 HÓA ĐƠN ĐIỀU CHỈNH CHO GỐC NĂM 2022–2023']];
s.getRange('A1:M1').format={font:{name:'Arial',size:14,bold:true,color:'#FFFFFF'},fill:'#203746',rowHeight:36};
s.getRange('A2:M2').merge();s.getRange('A2').values=[['37 hóa đơn điều chỉnh cho gốc năm 2022; 250 hóa đơn điều chỉnh cho gốc năm 2023.']];
s.getRange('A3:M3').merge();s.getRange('A3').values=[['Ngoài phạm vi xử lý hiện tại: chỉ xử lý hóa đơn gốc từ 01/01/2024 đến 30/06/2025 và các hóa đơn liên quan.']];
s.getRange('A2:M3').format={fill:'#E8F0F4',wrapText:true,rowHeight:28};
const columns=['STT','Ký hiệu điều chỉnh','Số HĐ điều chỉnh','Ngày HĐ điều chỉnh','Ký hiệu gốc','Số HĐ gốc','Ngày HĐ gốc','Năm gốc','Tên người mua trên HĐ điều chỉnh','Nguồn bảng tổng','Dòng bảng tổng','Nguồn liên kết','Dòng liên kết'];
s.getRange('A5:M5').values=[columns];
const day=x=>new Date(x+'T00:00:00Z');
const rows=list.map((x,i)=>{const h=headers.get(x.invoice.join('/'));if(!h)throw Error('Thiếu bảng tổng');return[i+1,...x.invoice,day(h.date),...x.parent,day(x.parent_date),Number(x.parent_date.slice(0,4)),h.name,h.source.replaceAll('\\','/'),h.row,x.source.replaceAll('\\','/'),x.row];});
s.getRange('A6:M292').values=rows;
const widths=[7,18,19,19,17,18,18,12,48,70,15,70,15];
widths.forEach((v,i)=>s.getRange(`${String.fromCharCode(65+i)}1:${String.fromCharCode(65+i)}292`).format.columnWidth=v);
for(const c of ['C','F'])s.getRange(`${c}6:${c}292`).setNumberFormat('00000000');
for(const c of ['D','G'])s.getRange(`${c}6:${c}292`).setNumberFormat('dd/mm/yyyy');
s.getRange('I6:M292').format.wrapText=true;
s.getRange('A5:M5').format={fill:'#203746',font:{name:'Arial',size:10,bold:true,color:'#FFFFFF'},wrapText:true,rowHeight:42,horizontalAlignment:'center'};
s.tables.add('A5:M292',true,'DS_287_HD_ngoai_pham_vi');
s.freezePanes.freezeRows(5);
w.recalculate();
const preview=await w.render({sheetName:s.name,range:'A5:I11',scale:1,format:'png'});
await fs.writeFile(path.join(dir,'list-287-preview.png'),new Uint8Array(await preview.arrayBuffer()));
const out=path.resolve('outputs/DANH_SACH_287_HD_DIEU_CHINH_GOC_2022_2023.xlsx');
await (await SpreadsheetFile.exportXlsx(w)).save(out);
console.log(out);
